from pathlib import Path
r=Path('/workspace/Java-portfolio/projects/09-byteguard'); pkg='io.github.cheshmakzanoon.portfolio.byteguard'
def write(d,n,s):
 p=r/d/'src/main/java'/Path(pkg.replace('.','/'))/d/(n+'.java');p.parent.mkdir(parents=True,exist_ok=True);p.write_text('package '+pkg+'.'+d+';\n'+s)
write('report','Finding','''import io.github.cheshmakzanoon.portfolio.byteguard.bytecode.*;import java.util.*;
public record Finding(String rule,String ruleVersion,String severity,String confidence,String fingerprint,String sourceDescriptor,String sinkDescriptor,InstructionId source,InstructionId sink,List<String> callPath,boolean provenanceTruncated,Location sourceLocation,Location sinkLocation,List<String> limitations) {
 public record Location(String uri,int line,String method,int instruction){}
 public Finding{callPath=List.copyOf(callPath);limitations=List.copyOf(limitations);}
}''')
write('report','FindingReporter','''import io.github.cheshmakzanoon.portfolio.byteguard.bytecode.*;import io.github.cheshmakzanoon.portfolio.byteguard.input.*;import io.github.cheshmakzanoon.portfolio.byteguard.interprocedural.*;import io.github.cheshmakzanoon.portfolio.byteguard.rules.*;import java.util.*;import java.nio.charset.StandardCharsets;
public final class FindingReporter {
 public List<Finding> findings(Analyzer.Result result){TreeMap<String,Finding> findings=new TreeMap<>();for(var summary:result.analysis().summaries().values())for(var flow:summary.flows().values())for(var source:flow.taint().labels().entrySet()){if(source.getKey().startsWith("P:")||(source.getValue()&flow.mask())==0)continue;int separator=source.getKey().indexOf('|');if(separator<0)continue;String at=source.getKey().substring(0,separator);int ordinal=at.lastIndexOf('@');InstructionId sourceId=new InstructionId(at.substring(0,ordinal),Integer.parseInt(at.substring(ordinal+1)));String fingerprint=BoundedJarReader.sha((flow.rule()+"|"+sourceId+"|"+flow.sink()).getBytes(StandardCharsets.UTF_8));Finding finding=new Finding(flow.rule(),RuleModels.VERSION,"warning",flow.taint().unknown()?"low":"medium",fingerprint,source.getKey().substring(separator+1),flow.descriptor(),sourceId,flow.sink(),flow.callPath(),flow.truncated(),location(sourceId,result),location(flow.sink(),result),List.of("Bounded modeled flows only; absence of findings is not a security guarantee.","Field-sensitive, object-insensitive heap and conservative array summaries."));findings.merge(fingerprint,finding,(a,b)->a.callPath().size()>=b.callPath().size()?a:b);}return List.copyOf(findings.values());}
 private Finding.Location location(InstructionId at,Analyzer.Result result){int dot=at.method().indexOf('.');String owner=at.method().substring(0,dot);var c=result.classes().get(owner);MethodIr method=c.methods().get(at.method());String file=method.sourceFile;String uri=file==null?owner+".class":(owner.contains("/")?owner.substring(0,owner.lastIndexOf('/')+1):"")+file;return new Finding.Location(uri,method.line(at.ordinal()),at.method(),at.ordinal());}
}''')
write('report','SarifExporter','''import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import io.github.cheshmakzanoon.portfolio.byteguard.interprocedural.*;import io.github.cheshmakzanoon.portfolio.byteguard.rules.*;import java.util.*;import java.io.*;import java.nio.file.*;
public final class SarifExporter {
 private final ObjectMapper mapper=new ObjectMapper();
 public ObjectNode report(Analyzer.Result analysis,List<Finding> findings,Set<String> baseline){ObjectNode root=mapper.createObjectNode();root.put("version","2.1.0");root.put("$schema","https://schemastore.azurewebsites.net/schemas/json/sarif-2.1.0-rtm.5.json");ObjectNode run=root.putArray("runs").addObject();ObjectNode driver=run.putObject("tool").putObject("driver");driver.put("name","ByteGuard");driver.put("version",RuleModels.VERSION);driver.put("informationUri","https://github.com/cheshmakzanoon-ops/Java-portfolio");ArrayNode rules=driver.putArray("rules");for(String id:new TreeSet<>(new RuleModels().rules())){ObjectNode rule=rules.addObject();rule.put("id",id);rule.put("name",id.replace("-",""));rule.putObject("shortDescription").put("text",description(id));rule.putObject("defaultConfiguration").put("level","warning");rule.putObject("properties").put("ruleVersion",RuleModels.VERSION);}
 ArrayNode results=run.putArray("results");for(Finding finding:findings){ObjectNode node=results.addObject();node.put("ruleId",finding.rule());node.put("level",finding.severity());node.putObject("message").put("text",finding.sourceDescriptor()+" reaches "+finding.sinkDescriptor()+" under model "+finding.ruleVersion());node.putObject("partialFingerprints").put("byteguard/v1",finding.fingerprint());node.put("baselineState",baseline.contains(finding.fingerprint())?"unchanged":"new");node.putArray("locations").add(location(finding.sinkLocation()));ArrayNode threads=node.putArray("codeFlows").addObject().putArray("threadFlows");ArrayNode steps=threads.addObject().putArray("locations");steps.addObject().set("location",location(finding.sourceLocation()));for(String call:finding.callPath()){ObjectNode step=steps.addObject();ObjectNode loc=step.putObject("location");loc.putObject("message").put("text",call);}steps.addObject().set("location",location(finding.sinkLocation()));ObjectNode props=node.putObject("properties");props.put("confidence",finding.confidence());props.put("provenanceTruncated",finding.provenanceTruncated());props.put("sourceBytecode",finding.source().toString());props.put("sinkBytecode",finding.sink().toString());props.set("modelLimitations",mapper.valueToTree(finding.limitations()));}
 ObjectNode invocation=run.putArray("invocations").addObject();invocation.put("executionSuccessful",!analysis.analysis().partial());ArrayNode notifications=invocation.putArray("toolExecutionNotifications");for(String diagnostic:analysis.analysis().diagnostics()){ObjectNode notification=notifications.addObject();notification.put("level",diagnostic.startsWith("RESOURCE_LIMIT")?"error":"warning");notification.putObject("message").put("text",diagnostic);}ObjectNode props=run.putObject("properties");props.put("partial",analysis.analysis().partial());props.put("workUnits",analysis.analysis().work());props.put("applicationClasses",analysis.classes().values().stream().filter(c->c.application()).count());props.put("unknownCalls",analysis.analysis().diagnostics().stream().filter(d->d.startsWith("UNKNOWN_CALL")).count());props.set("unfinishedFrontier",mapper.valueToTree(analysis.analysis().unfinished()));return root;}
 private String description(String rule){return switch(rule){case "BG-SQL-TEXT"->"External input in SQL command text";case "BG-SHELL-COMMAND"->"External input in modeled shell -c command";default->"External input in filesystem access path";};}
 private ObjectNode location(Finding.Location loc){ObjectNode node=mapper.createObjectNode();ObjectNode physical=node.putObject("physicalLocation");physical.putObject("artifactLocation").put("uri",loc.uri());if(loc.line()>0)physical.putObject("region").put("startLine",loc.line());node.putArray("logicalLocations").addObject().put("fullyQualifiedName",loc.method());node.putObject("properties").put("instructionOrdinal",loc.instruction());return node;}
 public void write(Path path,Object value)throws IOException{Path parent=path.toAbsolutePath().getParent();Files.createDirectories(parent);mapper.writerWithDefaultPrettyPrinter().writeValue(path.toFile(),value);}
 public Set<String> baseline(Path path)throws IOException{if(Files.size(path)>8*1024*1024)throw new IOException("baseline exceeds 8 MiB");JsonNode root=mapper.readTree(path.toFile());TreeSet<String> fingerprints=new TreeSet<>();JsonNode runs=root.path("runs");if(!runs.isArray())throw new IOException("baseline must be SARIF with exact byteguard/v1 fingerprints");for(JsonNode run:runs)for(JsonNode result:run.path("results")){String fp=result.path("partialFingerprints").path("byteguard/v1").asText();if(!fp.matches("[0-9a-f]{64}"))throw new IOException("invalid exact baseline fingerprint");fingerprints.add(fp);}return Set.copyOf(fingerprints);}
}''')
